// Detailed locations, batch 4: interiors (standard: references/detail.md)
const S=require('./stage.js');const Dt=require('./detail.js');const D2=require('./detail2.js');const D3=require('./detail3.js');const D4=require('./detail4.js');
const {PL,quad}=D2;const {crowdReal}=require('./crowd.js');const L7={};const cam=(PH=470,vx=960)=>S.Cam({vx,PH});
const T=D4.txtAt;const box=S.box;
const W={plaster:c=>(C,M,a,b,cc,d)=>D2.plaster(C,M,a,b,cc,d,{col:c}),paper:(c,st)=>(C,M,a,b,cc,d)=>D2.wallpaper(C,M,a,b,cc,d,{col:c,stripe:st}),tile:(c,g)=>(C,M,a,b,cc,d)=>D4.tileWall(C,M,a,b,cc,d,{col:c,grout:g}),brick:c=>(C,M,a,b,cc,d)=>D2.brick(C,M,a,b,cc,d,{col:c,mortar:S.shade(c,-.35),grime:.15}),concrete:c=>(C,M,a,b,cc,d)=>D2.concrete(C,M,a,b,cc,d,{col:c}),panel:c=>(C,M,a,b,cc,d)=>D3.panelWall(C,M,a,b,cc,d,{col:c}),
 wains:(top,bot)=>(C,M,a,b,cc,d)=>D2.plaster(C,M,a,b,1,d,{col:top})+D3.panelWall(C,M,a,b,0,1,{col:bot,step:.8})+S.poly(quad(C,M,a,b,.98,1.06),S.shade(bot,.1),'#3a2a1a',1)};
const F={wood:c=>(C,a,b,cc,d)=>D2.woodFloor(C,a,b,cc,d,{col:c}),tile:(c,c2,t)=>(C,a,b,cc,d)=>D2.tileFloor(C,a,b,cc,d,{col:c,col2:c2,t:t??.5}),concrete:c=>(C,a,b,cc,d)=>D2.concreteFloor(C,a,b,cc,d,{col:c})};
const room=(C,o)=>D2.room(C,o);
const lights=(C,Hc,zs,xs=[0],col='#fff6e0')=>{let s='';for(const z of zs)for(const x of xs){const [px,py]=C.P(x,Hc-.01,z),k=C.k(z)*C.U;s+=`<rect x="${px-.5*k}" y="${py-.03*k}" width="${k}" height="${.06*k}" rx="3" fill="${col}"/>`+S.glow(px,py+.1*k,1.1*k,col,.32);}return s;};
const ret=(C,bg,o={})=>({C,bg,fg:'',spots:o.spots??[[-.6,4.5],[.7,4.7]],rim:o.rim??'#ffe2b0',cast:o.cast??[1,.15],grade:o.grade??['#fff0d8',.42],amb:o.amb??'ambRoom'});

