 bg+=D2.rug(C,-1.2,1,2.2,3.8,{col:'#ffd24a',col2:'#3ac0a0'})+D2.plant(C,-3.2,7,{h:.9})+D4.windowSide(C,-RW,3,5,1,2.1,{curtains:'#ffd24a'});
