 {const [x,y]=C.P(-3.3,0,4),k=C.k(4)*C.U;bg+=`<path d="M${x},${y} L${x},${y-1.5*k}" stroke="#3a3a40" stroke-width="3"/><path d="M${x-.25*k},${y-1.5*k} L${x+.25*k},${y-1.5*k} L${x+.18*k},${y-1.85*k} L${x-.18*k},${y-1.85*k}Z" fill="#f2e2c0" stroke="#2a2030" stroke-width="1.2"/>`+S.glow(x,y-1.6*k,.8*k,'#ffe8a0',.5);}
