 for(const sx of [-1,1]){const q=[C.P(sx*RW,1,.5),C.P(sx*RW,1,Zb),C.P(sx*.3,Hc,Zb),C.P(sx*.3,Hc,.5)];bg+=S.poly(q,'#7a5a3a','#2a1a10',2);for(let i=1;i<9;i++){const t=i/9,X=sx*RW+(sx*.3-sx*RW)*t,Y=1+(Hc-1)*t;bg+=`<path d="M${C.P(X,Y,.5).join(',')} L${C.P(X,Y,Zb).join(',')}" stroke="#4a3220" stroke-width="2"/>`;}for(let z=1.5;z<Zb;z+=1.5)bg+=`<path d="M${C.P(sx*RW,1,z).join(',')} L${C.P(sx*.3,Hc,z).join(',')}" stroke="#5a3a20" stroke-width="${8*C.k(z)}"/>`;}
 {const [x,y]=C.P(0,1.8,Zb-.02),k=C.k(Zb)*C.U;bg+=`<circle cx="${x}" cy="${y}" r="${.5*k}" fill="#e8d8b0" stroke="#3a2a1a" stroke-width="4"/><path d="M${x-.5*k},${y} L${x+.5*k},${y} M${x},${y-.5*k} L${x},${y+.5*k}" stroke="#3a2a1a" stroke-width="4"/>`;const c=C.P(-1,0,Zb-3.5),d=C.P(1.6,0,Zb-3.5);bg+=`<path d="M${x-.4*k},${y-.3*k} L${x+.4*k},${y-.3*k} L${d[0]},${d[1]} L${c[0]},${c[1]}Z" fill="#fff2c8" opacity=".12"/>`+S.dust([[x-.4*k,y-.3*k],[x+.4*k,y-.3*k],d,c],70);}
 bg+=D2.crate(C,-2.4,6.4,{w:.8,h:.6})+D2.crate(C,-2.3,6.5,{w:.6,h:.45}).replace(/y0:0/,'')+D2.crate(C,2.6,5.8,{w:.7,h:.5,col:'#a8845a'})+D2.crate(C,-1.4,7,{w:.5,h:.4});
